          if (ram[ram[pc+1]][3:0] == `MOVFSI) begin
            cache[cc] <= safe_rom[ram[pc+1]+1] + regfile[ram[ram[pc+1]][5:4]];
            cache_rdy[cc] <= 1;
            cache_v[cc] <= ram[safe_rom[ram[pc+1]+1]] + regfile[ram[ram[pc+1][5:4]]];
