#!/usr/bin/env python3
from pwn import *
import binascii

# Memory image construction
def create_memory_image():
    # Initialize 256-byte memory image with zeros
    mem = bytearray(256)

    # Test sequence
    # Each instruction is 2 bytes
    instructions = [
        0x0600,  # RDTM to get initial timing
        0x0100,  # MOVF from address 0 
        0x0600,  # RDTM after first read
        0x0500,  # FLUSH to clear cache
        0x0600,  # RDTM after flush
        0x0100,  # MOVF from address 0 again
        0x0600,  # RDTM final timing
        0x0700   # HALT
    ]

    # Place instructions at start of memory
    for i, instr in enumerate(instructions):
        mem[i*2] = instr >> 8
        mem[i*2 + 1] = instr & 0xFF

    return bytes(mem)

# Format memory image (16 bytes per line)
def format_memory(mem):
    return '\n'.join(binascii.hexlify(mem[i:i+16]).decode() 
                    for i in range(0, len(mem), 16))

# Connect and test
def test_cache_timing():
    # Create memory image
    mem = create_memory_image()

    # Connect to server
    conn = remote('rev.chal.csaw.io', 8000)

    # Send memory image
    conn.sendline(format_memory(mem).encode())

    # Get results
    results = []
    while True:
        try:
            line = conn.recvline().decode().strip()
            if 'HALT' in line:
                break
            if 'cycles' in line.lower():
                results.append(line)
        except EOFError:
            break

    conn.close()
    return results

def main():
    results = test_cache_timing()
    print("\nCache Timing Results:")
    for r in results:
        print(r)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import binascii
import time

def create_memory_image(test_addr):
    # Initialize 256-byte memory image with zeros
    mem = bytearray(256)

    # Test sequence with parameterized address
    instructions = [
        0x0600,  # RDTM initial
        0x0100 | test_addr,  # MOVF from test_addr
        0x0600,  # RDTM after first read
        0x0500,  # FLUSH cache
        0x0600,  # RDTM after flush
        0x0100 | test_addr,  # MOVF from test_addr again
        0x0600,  # RDTM final
        0x0700   # HALT
    ]

    # Place instructions at start of memory
    for i, instr in enumerate(instructions):
        mem[i*2] = instr >> 8
        mem[i*2 + 1] = instr & 0xFF

    # Add some data at test addresses
    for i in range(0, 256, 16):
        mem[i] = 0xAA

    return bytes(mem)

def format_memory(mem):
    return '\n'.join(binascii.hexlify(mem[i:i+16]).decode() 
                    for i in range(0, len(mem), 16))

def test_address(addr):
    mem = create_memory_image(addr)

    try:
        conn = remote('rev.chal.csaw.io', 8000)
        conn.sendline(format_memory(mem).encode())

        timings = []
        while True:
            try:
                line = conn.recvline().decode().strip()
                if 'HALT' in line:
                    break
                if 'cycles' in line.lower():
                    # Extract timing value
                    try:
                        cycles = int(line.split()[-1])
                        timings.append(cycles)
                    except:
                        pass
            except EOFError:
                break

        conn.close()
        return timings
    except:
        return None

def main():
    print("Testing cache timing patterns across different addresses...")
    results = {}

    # Test addresses at different offsets
    test_addresses = [0, 16, 32, 48, 64, 128]

    for addr in test_addresses:
        print(f"\nTesting address 0x{addr:02x}")
        timings = test_address(addr)
