from pwn import *
import time

def send_memory_image(filename):
    conn = remote('rev.chal.csaw.io', 8000)

    with open(filename, 'r') as f:
        hex_data = f.read()

    # Send each line
    for line in hex_data.strip().split('\n'):
        conn.sendline(line.encode())
        time.sleep(0.1)  # Small delay between lines

    # Collect and analyze output
    cycles = []
    while True:
        try:
            line = conn.recvline().decode().strip()
            print(line)
            if 'cycles' in line.lower():
                try:
                    cycle_count = int(line.split(':')[1].strip())
                    cycles.append(cycle_count)
                except:
                    pass
            if 'HALT' in line:
                break
        except EOFError:
            break

    conn.close()
    return cycles

def main():
    print("Testing cache timing with address 0x40...")
    cycles = send_memory_image('test_cache.hex')

    if cycles:
        print("\nTiming Analysis:")
