            cached_access = cycles[3] - cycles[2]
            print(f"First access time: {first_access} cycles")
            print(f"Cached access time: {cached_access} cycles")
            print(f"Timing difference: {first_access - cached_access} cycles")

if __name__ == '__main__':
    main()

