from pwn import *
import time
context.log_level = 'error'  # Reduce noise

def measure_single_key_attempt(io, test_input):
    try:
        start = time.perf_counter_ns()
        io.sendline(test_input)
        io.recvuntil(b'Invalid', timeout=1)
        end = time.perf_counter_ns()
        return end - start
    except:
        return 0

def extract_key():
    key = bytearray(8)
    attempts = 0
    max_attempts = 3

    while attempts < max_attempts:
        try:
            io = remote('rev.chal.csaw.io', 8000, timeout=5)
            io.recvuntil(b'>', timeout=2)

            # Test known patterns to calibrate timing
            base_timing = measure_single_key_attempt(io, b'0' * 16)
            if base_timing == 0:
                raise Exception("Failed to get base timing")

            # For each byte position
            for pos in range(8):
                max_timing = 0
                best_val = 0

                # Try values that are likely to be ASCII
                for val in range(32, 127):
                    test_key = key[:]
                    test_key[pos] = val
                    timing = measure_single_key_attempt(io, test_key.hex().encode())

                    if timing > max_timing:
                        max_timing = timing
                        best_val = val

                key[pos] = best_val
                print(f"Position {pos}: {chr(best_val)} ({hex(best_val)})")

            io.close()
            return bytes(key)

        except Exception as e:
            print(f"Attempt {attempts + 1} failed: {str(e)}")
            attempts += 1
            try:
                io.close()
            except:
                pass
            time.sleep(1)

    raise Exception("Failed to extract key after multiple attempts")

def verify_key(key):
    try:
        io = remote('rev.chal.csaw.io', 8000, timeout=5)
        io.recvuntil(b'>', timeout=2)
        io.sendline(key.hex().encode())
        resp = io.recvuntil(b'>', timeout=2)
        io.close()
        return b'emode' in resp
    except:
        return False

def get_flag(key):
    try:
        io = remote('rev.chal.csaw.io', 8000, timeout=5)
        io.recvuntil(b'>', timeout=2)

        # Enter emode
        io.sendline(key.hex().encode())
        io.recvuntil(b'>', timeout=2)

        # Read memory locations
        for addr in range(0x1000):
            io.sendline(f"MOVFS {addr}".encode())
            try:
                resp = io.recvuntil(b'>', timeout=1)
                if b'flag{' in resp:
                    start = resp.find(b'flag{')
                    end = resp.find(b'}', start)
                    if end != -1:
                        return resp[start:end+1].decode()
            except:
                continue

        io.close()
    except:
        pass
    return None

def main():
    try:
        print("[+] Starting key extraction...")
        key = extract_key()
        print(f"[+] Extracted key: {key.hex()}")

        print("[+] Verifying key...")
        if verify_key(key):
            print("[+] Key verified successfully!")

            print("[+] Attempting to read flag...")
            flag = get_flag(key)

            if flag:
                print(f"[+] Found flag: {flag}")
                return flag
            else:
                print("[-] Failed to read flag")
        else:
            print("[-] Key verification failed")

    except Exception as e:
        print(f"[-] Error: {str(e)}")

if __name__ == '__main__':
    main()

from pwn import *
import time
import statistics
context.log_level = 'error'

def measure_timing(candidate):
    timings = []
    for _ in range(3):  # Multiple measurements for accuracy
        try:
            io = remote('rev.chal.csaw.io', 8000, timeout=2)
            io.recvuntil(b'>', timeout=1)

            start = time.perf_counter_ns()
            io.sendline(candidate.hex().encode())
            io.recvuntil(b'Invalid', timeout=1)
            end = time.perf_counter_ns()

            timing = end - start
            if timing > 0:
                timings.append(timing)

            io.close()
        except:
            pass
        time.sleep(0.1)  # Small delay between attempts

    return statistics.mean(timings) if timings else 0

def extract_key():
    key = bytearray(8)
    print("[+] Starting cache timing analysis...")

    # Do multiple passes to refine the key
    for pass_num in range(2):
        print(f"[+] Pass {pass_num + 1}")

        for pos in range(8):
            max_timing = 0
            best_val = 0

            # Try values focusing on ASCII range first
            value_ranges = [(32, 127)] if pass_num == 0 else [(0, 255)]

            for r in value_ranges:
                for val in range(r[0], r[1]):
                    test_key = key[:]
                    test_key[pos] = val

                    timing = measure_timing(test_key)

                    if timing > max_timing:
                        max_timing = timing
                        best_val = val

            key[pos] = best_val
            if pass_num == 1:  # Only print final results
                print(f"Position {pos}: {hex(best_val)} ({chr(best_val) if 32 <= best_val <= 126 else '?'})")

    return bytes(key)

def verify_key(key):
    for _ in range(3):  # Multiple verification attempts
        try:
            io = remote('rev.chal.csaw.io', 8000, timeout=2)
            io.recvuntil(b'>', timeout=1)
            io.sendline(key.hex().encode())
            resp = io.recvuntil(b'>', timeout=1)
            io.close()

            if b'emode' in resp:
                return True
        except:
            pass
        time.sleep(0.5)
    return False

def read_flag(key):
    try:
        io = remote('rev.chal.csaw.io', 8000, timeout=2)
        io.recvuntil(b'>', timeout=1)

        # Enter emode
        io.sendline(key.hex().encode())
        io.recvuntil(b'>', timeout=1)

        # Try to read memory locations where flag might be
        for base in [0x0, 0x100, 0x200, 0x300]:  # Common memory regions
            for offset in range(0, 0x100, 4):  # Read in chunks
                addr = base + offset
                io.sendline(f"MOVFS {hex(addr)}".encode())
                try:
                    resp = io.recvuntil(b'>', timeout=1)
                    if b'flag{' in resp:
                        start = resp.find(b'flag{')
                        end = resp.find(b'}', start)
                        if end != -1:
                            return resp[start:end+1].decode()
                except:
                    continue

        io.close()
    except:
        pass
    return None

def main():
    try:
        # Extract key using cache timing analysis
        key = extract_key()
        print(f"[+] Final key: {key.hex()}")

        # Verify the extracted key
        print("[+] Verifying key...")
        if verify_key(key):
            print("[+] Key verified! Entering emode...")

            # Try to read the flag
            print("[+] Searching for flag...")
            flag = read_flag(key)

            if flag:
                print(f"[+] Found flag: {flag}")
                return flag
            else:
                print("[-] Could not find flag")
        else:
            print("[-] Key verification failed")

    except Exception as e:
        print(f"[-] Error: {str(e)}")

if __name__ == '__main__':
    main()

